async function helperAvailable($: EngineInterface): Promise<boolean> {
  if (helperUsable !== null) return helperUsable
  try {
    helperUsable = (await $.process.run(['xcode-select', '-p'], { timeoutMs: 5000 })).exitCode === 0
  } catch {
